mapper.select:
SELECT id, underpass_id, car_num, entry_plate_log_id, exit_plate_log_id, status, entry_at, exit_at
  FROM underpass_transit
 WHERE underpass_id = #{underpassId}
   AND status IN ('IN_TRANSIT', 'REMAINING')
   AND regexp_replace(car_num, '[^0-9]', '', 'g') = #{digits}
   AND length(car_num) = length(#{carNum})
   AND entry_at BETWEEN #{from} AND #{to}
 ORDER BY entry_at DESC
 LIMIT 1

mapper.update:
UPDATE underpass_transit
   SET status = 'EXITED',
       exit_plate_log_id = #{exitPlateLogId},
       exit_at = #{exitAt}
 WHERE id = #{id}

